using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Observation;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Observational;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.DependencyInjection;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Observational;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Visibility;
using Microsoft.Extensions.DependencyInjection;

namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.ObservationalAndVisibility;

public sealed class AstronomyVisibilityWindowValidationRuleTests{ static AstronomyKnowledgeValidationResult V(params AstronomyVisibilityWindow[] w)=>ObservationalVisibilityValidationFixture.Validate(new AstronomyVisibilityWindowsPayload(new("typed.observational.visibility-windows.v1"),ObservationalVisibilityValidationFixture.ObservationContext(),w),s=>s.AddAstronomyVisibilityValidation());[Fact] public void Valid_window_passes()=>Assert.Empty(V(ObservationalVisibilityValidationFixture.VisibilityWindow()).Issues);[Fact] public void Invalid_start_end_order_is_detected_or_constructor_protected()=>Assert.Throws<ArgumentException>(()=>new AstronomyObservationTimeWindow(ObservationalVisibilityValidationFixture.T2,ObservationalVisibilityValidationFixture.T0));[Fact] public void Exact_duplicate_window_is_detected_or_constructor_protected()=>Assert.Throws<ArgumentException>(()=>new AstronomyVisibilityWindowsPayload(new("typed.observational.visibility-windows.v1"),ObservationalVisibilityValidationFixture.ObservationContext(),[ObservationalVisibilityValidationFixture.VisibilityWindow(),ObservationalVisibilityValidationFixture.VisibilityWindow()]));[Fact] public void Same_time_range_with_different_method_is_handled_by_identity_policy()=>Assert.DoesNotContain(V(ObservationalVisibilityValidationFixture.VisibilityWindow(assessment:ObservationalVisibilityValidationFixture.Assessment(method:AstronomyVisibilityMethod.NakedEye)),ObservationalVisibilityValidationFixture.VisibilityWindow(assessment:ObservationalVisibilityValidationFixture.Assessment(method:AstronomyVisibilityMethod.Binocular),note:"binocular")).Issues,i=>i.Code==AstronomyVisibilityValidationCodes.WindowDuplicate);[Fact] public void Equivalent_partial_overlap_produces_warning_when_policy_exists(){var i=Assert.Single(V(ObservationalVisibilityValidationFixture.VisibilityWindow(),ObservationalVisibilityValidationFixture.VisibilityWindow(start:ObservationalVisibilityValidationFixture.T1,end:new DateTimeOffset(2026,8,1,3,0,0,TimeSpan.Zero),peak:ObservationalVisibilityValidationFixture.T2,note:"overlap")).Issues,x=>x.Code==AstronomyVisibilityValidationCodes.WindowOverlap);Assert.Equal(AstronomyKnowledgeValidationSeverity.Warning,i.Severity);Assert.Equal("$.windows[1]",i.Path);}[Fact] public void Different_method_overlap_is_allowed_when_contract_allows_it()=>Assert.DoesNotContain(V(ObservationalVisibilityValidationFixture.VisibilityWindow(),ObservationalVisibilityValidationFixture.VisibilityWindow(start:ObservationalVisibilityValidationFixture.T1,end:new DateTimeOffset(2026,8,1,3,0,0,TimeSpan.Zero),assessment:ObservationalVisibilityValidationFixture.Assessment(method:AstronomyVisibilityMethod.Binocular),peak:ObservationalVisibilityValidationFixture.T2,note:"overlap2")).Issues,i=>i.Code==AstronomyVisibilityValidationCodes.WindowOverlap);[Fact] public void Blank_window_note_is_rejected_or_constructor_protected()=>Assert.Throws<ArgumentException>(()=>ObservationalVisibilityValidationFixture.VisibilityWindow(note:" "));[Fact] public void Issue_paths_reference_the_correct_window_index()=>Equivalent_partial_overlap_produces_warning_when_policy_exists();}